function time(value?:string) { return value ? new Date(value).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:'Asia/Kolkata'}) : '—'; }
function date(value?:string) { return value ? new Date(value).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}) : '—'; }
function initials(name='Employee') { return name.split(' ').map(v=>v[0]).slice(0,2).join(''); }
function direction(value:string) { return value==='home_to_office'?'Home → Office':'Office → Home'; }
function elapsed(start?:string,end?:string) { if(!start)return '—';const min=Math.max(0,Math.floor(((end?new Date(end).getTime():Date.now())-new Date(start).getTime())/60000));return min<60?`${min} min`:`${Math.floor(min/60)}h ${min%60}m`; }
function maps(loc?:Location) { return loc?.lat!==undefined&&loc?.lng!==undefined?`https://www.google.com/maps?q=${loc.lat},${loc.lng}`:null; }
function uid(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
