    {view==='overview'&&<><div className="page-heading"><div><div className="eyebrow">THE NIGHT SHIFT, IN SIGHT</div><h1>Every ride. Everyone safe.</h1><p>A little visibility. A lot of peace of mind.</p></div><button className="btn secondary date-chip" onClick={()=>{setView('reports');}}><CalendarDays size={16}/>{date(new Date().toISOString())}<ChevronDown size={15}/></button></div><div className="shift-banner"><div className="shift-icon"><Moon size={23}/><span/></div><div><h3>{trips.some(t=>t.status==='active')?'Your team is on the move.':'Ready for a safe night.'}</h3><p>{`${trips.filter(t=>t.status==='active').length} active journeys. Check-ins and arrivals appear here automatically.`}</p></div><span className="live-tag"><i/>Updates every 15s</span><div className="banner-route"><Building2 size={20}/><span/><CarFront size={23}/><span/><Home size={20}/></div></div><div className="stats-grid">{[{title:'On the way',value:trips.filter(t=>t.status==='active').length,sub:'Active cab journeys',Icon:CarFront,color:'green'},{title:'Arrived safely',value:trips.filter(t=>t.status==='completed').length,sub:'Completed journeys',Icon:ShieldCheck,color:'lime'},{title:'Safety alerts',value:openAlerts.length,sub:openAlerts.length?'Needs your attention':'No open SOS alerts',Icon:Bell,color:'orange'},{title:'Your team',value:employees.filter(e=>e.active).length,sub:'Active employee accounts',Icon:Users,color:'blue'}].map((s,i)=><button key={s.title} className={`stat-card ${i===2&&s.value>0?'alert-stat':''}`} onClick={()=>{setView(i===2?'alerts':i===3?'people':'journeys');setTripFilter(i===0?'active':i===1?'completed':'all');}}><div><span>{s.title}</span><span className={`stat-icon ${s.color}`}><s.Icon size={19}/></span></div><strong>{s.value.toString().padStart(2,'0')}</strong><p>{i===1&&<CheckCircle2 size={12}/>} {s.sub}</p></button>)}</div><div className="overview-grid"><section className="card journeys-card"><div className="card-heading"><div><h2>Recent journeys <span className="count-pill">{trips.length}</span></h2><p>From the first check-in to a safe arrival.</p></div><button className="text-link" onClick={()=>{setView('journeys');setTripFilter('all');}}>View all <ArrowRight size={14}/></button></div><div className="table-tools"><div className="segmented">{[['all','All journeys'],['active','On the way'],['completed','Arrived']].map(([id,label])=><button className={tripFilter===id?'selected':''} key={id} onClick={()=>setTripFilter(id)}>{label}</button>)}</div><button className="icon-btn" aria-label="Refresh journeys" onClick={()=>load().then(()=>say('Journeys are up to date.')).catch(e=>say(e.message))}><RefreshCw size={16}/></button></div>{journeyTable}<div className="card-foot"><ShieldCheck size={14}/> Locations captured at check-in and arrival. No continuous tracking.</div></section><div className="right-column"><section className="card activity-card"><div className="card-heading"><h2>Latest check-ins</h2><span className="pulse-dot"/></div><div className="activity-list">{trips.slice(0,4).map((t,i)=><button key={t.id} className="activity-item" onClick={()=>setTripDetail(t)}><span className={`activity-icon ${t.status==='completed'?'done':''}`}>{t.status==='completed'?<Check size={15}/>:<CarFront size={15}/>}</span><span><strong>{t.employeeName?.split(' ')[0]} {t.status==='completed'?'arrived safely':'got in the cab'}</strong><small>{t.status==='completed'?'A journey, safely completed.':direction(t.direction)}</small><time>{time(t.arrivedAt||t.boardedAt)}</time></span></button>)}{!trips.length&&<p className="small-empty">Check-ins will appear as your team starts travelling.</p>}</div></section><section className="automation-card"><div className="automation-logo"><Workflow size={21}/><span className={workerConnected?'connected-light':'pending-light'}/></div><h3>{workerConnected?'Connected with n8n':'A little help behind the scenes.'}</h3><p>Teams alerts, emails and daily logs. One connected workflow.</p><button onClick={()=>setView('automations')}>{workerConnected?'Manage automations':'Connect your automations'}<ArrowUpRight size={16}/></button></section></div></div><div className="dashboard-footer"><span><ShieldCheck size={14}/> Care that carries beyond office hours.</span><span>{locFilter==='all'?locations.map(l=>l.region.split(',')[0]).join(' · '):locations.find(l=>l.id===locFilter)?.region} <i/> Asia/Kolkata</span></div></>}
